<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { getEmailMessage, getEmailMessages } from '@/api/adminOperationsApi'
import type { AdminEmailMessage } from '@/models/AdminEmailMessage'
import type { AdminEmailMessageDetails } from '@/models/AdminEmailMessageDetails'
import { useAdminCurrentUserStore } from '@/stores/adminCurrentUserStore'
const currentUserStore = useAdminCurrentUserStore()
const items = ref<AdminEmailMessage[]>([]), selected = ref<AdminEmailMessageDetails | null>(null), search = ref(''), status = ref(''), error = ref(''), isDetailsLoading = ref(false)
const canManage = computed(() => currentUserStore.isSystem || currentUserStore.currentUser?.permissions.includes('Admin.Communications.Manage') === true)
onMounted(load)
async function load() { try { items.value = (await getEmailMessages(search.value, status.value)).items } catch { error.value = 'Не удалось загрузить письма.' } }
async function open(item: AdminEmailMessage) { isDetailsLoading.value = true; error.value = ''; try { selected.value = await getEmailMessage(item.id) } catch { error.value = 'Не удалось загрузить письмо.' } finally { isDetailsLoading.value = false } }
function date(value: string | null) { return value ? new Intl.DateTimeFormat('ru-RU', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : '—' }
</script>
<template><section class="operations-page"><h1>История email</h1><div class="operations-toolbar"><input v-model="search" type="search" placeholder="Email, тема или ID" @keyup.enter="load"><SearchSelect v-model="status" :options="[{ value: '', label: 'Все статусы' }, { value: 'pending', label: 'Ожидает' }, { value: 'queued', label: 'В очереди' }, { value: 'retrying', label: 'Повторная попытка' }, { value: 'simulated', label: 'Имитация' }, { value: 'sent', label: 'Отправлено' }, { value: 'delivered', label: 'Доставлено' }, { value: 'opened', label: 'Открыто' }, { value: 'clicked', label: 'Переход' }, { value: 'failed', label: 'Ошибка' }]" @change="load" /><button class="secondary-button" @click="load">Найти</button><RouterLink v-if="canManage" class="primary-button link-button" to="/communications/email-compose">Написать письмо</RouterLink></div><div v-if="error" class="form-message form-message--error">{{ error }}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Получатель</th><th>Тема</th><th>Дата</th><th>Статус</th><th>Открытия</th><th>Переходы</th></tr></thead><tbody><tr v-for="item in items" :key="item.id" @click="open(item)"><td>{{ item.toEmail }}</td><td>{{ item.subject }}</td><td>{{ date(item.sentAt || item.createdAt) }}</td><td>{{ item.lastEventCode || item.statusCode }}</td><td>{{ item.openCount }}</td><td>{{ item.clickCount }}</td></tr></tbody></table></div><div v-if="isDetailsLoading" class="modal-backdrop"><div class="modal-card modal-card--compact">Загрузка…</div></div><div v-if="selected" class="modal-backdrop" @click.self="selected = null"><div class="modal-card email-details"><div class="modal-heading"><strong>Письмо #{{ selected.id }}</strong><button @click="selected = null">×</button></div><dl class="details-list"><dt>Получатель</dt><dd>{{ selected.toEmail }}</dd><dt>Тема</dt><dd>{{ selected.subject }}</dd><dt>Создано</dt><dd>{{ date(selected.createdAt) }}</dd><dt>Отправлено</dt><dd>{{ date(selected.sentAt) }}</dd><dt>Статус</dt><dd>{{ selected.lastEventCode || selected.statusCode }}</dd><dt v-if="selected.errorMessage">Ошибка</dt><dd v-if="selected.errorMessage">{{ selected.errorMessage }}</dd></dl><iframe v-if="selected.htmlBody" class="email-preview" sandbox="" title="Содержимое письма" :srcdoc="selected.htmlBody"></iframe><pre v-else class="email-text">{{ selected.textBody }}</pre><div class="modal-actions"><button class="secondary-button" @click="selected = null">Закрыть</button></div></div></div></section></template>
